from pathlib import Path

root = Path('.')

profile_h = root / 'src/climate/runtime/Stage27ScheduleProfile.h'
text = profile_h.read_text()
old = '''bool buildMintScheduleProfile(std::uint8_t local_hour,\n                              ClimateScheduleConfigSnapshot& output) noexcept;\n'''
new = '''bool buildMintScheduleProfile(std::uint8_t local_hour,\n                              ClimateScheduleConfigSnapshot& output) noexcept;\n\nbool resolveMintScheduleProfile(const ClimateWallClockSnapshot& clock,\n                                ClimateScheduleConfigSnapshot& output) noexcept;\n'''
if text.count(old) != 1:
    raise SystemExit('Stage27ScheduleProfile.h marker mismatch')
profile_h.write_text(text.replace(old, new))

profile_cpp = root / 'src/climate/runtime/Stage27ScheduleProfile.cpp'
profile_cpp.write_text('''#include "climate/runtime/Stage27ScheduleProfile.h"\n\n#include "climate/runtime/EuropeWarsawTime.h"\n\nnamespace growbox::app::climate_io::runtime {\n\nbool buildMintScheduleProfile(std::uint8_t local_hour,\n                              ClimateScheduleConfigSnapshot& output) noexcept {\n  if (local_hour > 23U) {\n    output = {};\n    return false;\n  }\n\n  output = {};\n  output.sensor_timeout_ms = ::growbox::climate::kDefaultSensorTimeoutMs;\n  output.humidity_control_mode = ::growbox::climate::HumidityControlMode::Rh;\n  output.capabilities.heater = false;\n  output.capabilities.cooler = false;\n  output.capabilities.exhaust_fan = true;\n  output.capabilities.humidifier = true;\n  output.capabilities.dehumidifier = false;\n  output.capabilities.co2_doser = false;\n\n  const bool day = local_hour >= 6U && local_hour < 22U;\n  output.targets.air_temperature_c = day ? 24.5F : 21.5F;\n  output.targets.relative_humidity_pct = day ? 58.0F : 65.0F;\n  output.targets.air_vpd_kpa = day ? 1.2F : 0.9F;\n  output.targets.co2_enabled = false;\n  output.targets.co2_ppm = 0.0F;\n  output.schedule.light_level = day ? 1.0F : 0.0F;\n  return true;\n}\n\nbool resolveMintScheduleProfile(const ClimateWallClockSnapshot& clock,\n                                ClimateScheduleConfigSnapshot& output) noexcept {\n  if (!clock.valid) {\n    return false;\n  }\n\n  EuropeWarsawLocalTime local{};\n  if (!resolveEuropeWarsawLocalTime(clock.unix_time_s, local)) {\n    return false;\n  }\n\n  return buildMintScheduleProfile(local.hour, output);\n}\n\n} // namespace growbox::app::climate_io::runtime\n''')

runtime_cpp = root / 'src/climate/runtime/Stage27RuntimeAdapters.cpp'
text = runtime_cpp.read_text()
text = text.replace('#include "climate/runtime/EuropeWarsawTime.h"\n', '')
old = '''bool FixedStage27ScheduleConfigSource::resolve(std::uint64_t, const ClimateWallClockSnapshot& clock,\n                                               ClimateScheduleConfigSnapshot& output) noexcept {\n  if (!clock.valid) {\n    return false;\n  }\n\n  EuropeWarsawLocalTime local{};\n  if (!resolveEuropeWarsawLocalTime(clock.unix_time_s, local)) {\n    return false;\n  }\n\n  return buildMintScheduleProfile(local.hour, output);\n}\n'''
new = '''bool FixedStage27ScheduleConfigSource::resolve(std::uint64_t, const ClimateWallClockSnapshot& clock,\n                                               ClimateScheduleConfigSnapshot& output) noexcept {\n  return resolveMintScheduleProfile(clock, output);\n}\n'''
if text.count(old) != 1:
    raise SystemExit('Stage27RuntimeAdapters.cpp schedule resolver marker mismatch')
runtime_cpp.write_text(text.replace(old, new))

adapter_h = root / 'src/climate/runtime/Stage27ScheduleIntentAdapter.h'
adapter_h.parent.mkdir(parents=True, exist_ok=True)
adapter_h.write_text('''#pragma once\n\n#include "climate/ClimateCompositeInput.h"\n#include "climate/output/OutputIntents.h"\n\n#include <cstdint>\n\nnamespace growbox::app::climate_io::runtime {\n\nbool buildStage27ScheduleIntent(\n    std::uint64_t monotonic_ms, const ClimateWallClockSnapshot& clock, std::uint64_t sequence,\n    ::growbox::app::output::ScheduleIntent& output) noexcept;\n\n} // namespace growbox::app::climate_io::runtime\n''')

adapter_cpp = root / 'src/climate/runtime/Stage27ScheduleIntentAdapter.cpp'
adapter_cpp.write_text('''#include "climate/runtime/Stage27ScheduleIntentAdapter.h"\n\n#include "climate/Stage28dOutputBindings.h"\n#include "climate/runtime/Stage27ScheduleProfile.h"\n\nnamespace growbox::app::climate_io::runtime {\n\nbool buildStage27ScheduleIntent(\n    std::uint64_t monotonic_ms, const ClimateWallClockSnapshot& clock, std::uint64_t sequence,\n    ::growbox::app::output::ScheduleIntent& output) noexcept {\n  output = {};\n\n  ClimateScheduleConfigSnapshot profile{};\n  if (!resolveMintScheduleProfile(clock, profile)) {\n    return false;\n  }\n\n  ::growbox::app::output::ScheduleIntent intent{};\n  intent.metadata.sequence = sequence;\n  intent.metadata.monotonic_ms = monotonic_ms;\n  intent.metadata.source = ::growbox::app::output::OutputSource::Schedule;\n  intent.metadata.reason = ::growbox::app::output::OutputReason::ScheduleRequest;\n  if (!::growbox::app::output::setEndpointIntent(\n          intent.endpoints[0], stage28d::kScheduledLightEndpoint, profile.schedule.light_level)) {\n    return false;\n  }\n\n  output = intent;\n  return true;\n}\n\n} // namespace growbox::app::climate_io::runtime\n''')

test_cpp = root / 'test/test_stage27_schedule_intent/test_main.cpp'
test_cpp.parent.mkdir(parents=True, exist_ok=True)
test_cpp.write_text('''#include "climate/Stage28dOutputBindings.h"\n#include "climate/output/OutputIntents.h"\n#include "climate/runtime/Stage27ScheduleIntentAdapter.h"\n#include "climate/runtime/Stage27ScheduleProfile.h"\n\n#include <array>\n#include <cassert>\n#include <cstdint>\n\nnamespace {\n\nnamespace output = growbox::app::output;\nusing growbox::app::climate_io::ClimateScheduleConfigSnapshot;\nusing growbox::app::climate_io::ClimateWallClockSnapshot;\nusing growbox::app::climate_io::runtime::buildStage27ScheduleIntent;\nusing growbox::app::climate_io::runtime::resolveMintScheduleProfile;\nusing growbox::app::climate_io::stage28d::kScheduledLightEndpoint;\n\nClimateWallClockSnapshot clockAt(std::uint64_t unix_time_s) {\n  return {true, unix_time_s};\n}\n\noutput::ScheduleIntent intentAt(std::uint64_t unix_time_s, std::uint64_t sequence = 7U,\n                                std::uint64_t monotonic_ms = 1234U) {\n  output::ScheduleIntent intent{};\n  assert(buildStage27ScheduleIntent(monotonic_ms, clockAt(unix_time_s), sequence, intent));\n  return intent;\n}\n\nvoid assertSingleLampIntent(const output::ScheduleIntent& intent, float expected_level) {\n  assert(intent.metadata.source == output::OutputSource::Schedule);\n  assert(intent.metadata.reason == output::OutputReason::ScheduleRequest);\n  assert(output::endpointIntentActive(intent.endpoints[0]));\n  assert(intent.endpoints[0].endpoint == kScheduledLightEndpoint);\n  assert(intent.endpoints[0].level == expected_level);\n  assert(!output::endpointIntentActive(intent.endpoints[1]));\n  assert(!output::endpointIntentActive(intent.endpoints[2]));\n}\n\nvoid testMetadataAndSingleEndpoint() {\n  const auto intent = intentAt(1768453200ULL, 91U, 4567U); // Warsaw 06:00 winter\n  assertSingleLampIntent(intent, 1.0F);\n  assert(intent.metadata.sequence == 91U);\n  assert(intent.metadata.monotonic_ms == 4567U);\n}\n\nvoid testWarsawLightingBoundariesMatchExistingProfile() {\n  constexpr std::array<std::uint64_t, 8U> kEpochs{\n      1768453199ULL, // winter 05:59:59 local\n      1768453200ULL, // winter 06:00:00 local\n      1768510799ULL, // winter 21:59:59 local\n      1768510800ULL, // winter 22:00:00 local\n      1784087999ULL, // summer 05:59:59 local\n      1784088000ULL, // summer 06:00:00 local\n      1784145599ULL, // summer 21:59:59 local\n      1784145600ULL, // summer 22:00:00 local\n  };\n  constexpr std::array<float, 8U> kExpected{0.0F, 1.0F, 1.0F, 0.0F,\n                                            0.0F, 1.0F, 1.0F, 0.0F};\n\n  for (std::size_t i = 0U; i < kEpochs.size(); ++i) {\n    ClimateScheduleConfigSnapshot profile{};\n    const auto clock = clockAt(kEpochs[i]);\n    assert(resolveMintScheduleProfile(clock, profile));\n    const auto intent = intentAt(kEpochs[i], 100U + i, 500U + i);\n    assert(profile.schedule.light_level == kExpected[i]);\n    assertSingleLampIntent(intent, profile.schedule.light_level);\n  }\n}\n\nvoid testInvalidClockFailsClosedAndClearsIntent() {\n  output::ScheduleIntent intent{};\n  intent.metadata.source = output::OutputSource::Manual;\n  assert(output::setEndpointIntent(intent.endpoints[0], kScheduledLightEndpoint, 1.0F));\n\n  ClimateWallClockSnapshot invalid{};\n  assert(!buildStage27ScheduleIntent(1U, invalid, 2U, intent));\n  assert(intent.metadata.source == output::OutputSource::None);\n  assert(intent.metadata.reason == output::OutputReason::None);\n  for (const auto& endpoint : intent.endpoints) {\n    assert(!output::endpointIntentActive(endpoint));\n  }\n}\n\n} // namespace\n\nint main() {\n  testMetadataAndSingleEndpoint();\n  testWarsawLightingBoundariesMatchExistingProfile();\n  testInvalidClockFailsClosedAndClearsIntent();\n  return 0;\n}\n''')

src_cmake = root / 'src/CMakeLists.txt'
text = src_cmake.read_text()
old = '      "climate/runtime/Stage27ScheduleProfile.cpp"\n      "climate/runtime/Stage27RuntimeAdapters.cpp"\n'
new = '      "climate/runtime/Stage27ScheduleProfile.cpp"\n      "climate/runtime/Stage27ScheduleIntentAdapter.cpp"\n      "climate/runtime/Stage27RuntimeAdapters.cpp"\n'
if text.count(old) != 1:
    raise SystemExit('src/CMakeLists.txt marker mismatch')
src_cmake.write_text(text.replace(old, new))

host_cmake = root / 'test/host/CMakeLists.txt'
text = host_cmake.read_text()
marker = '''target_compile_features(stage27_schedule_profile_tests PRIVATE cxx_std_17)\ntarget_compile_options(stage27_schedule_profile_tests PRIVATE -Wall -Wextra -Wpedantic)\n\n'''
block = '''target_compile_features(stage27_schedule_profile_tests PRIVATE cxx_std_17)\ntarget_compile_options(stage27_schedule_profile_tests PRIVATE -Wall -Wextra -Wpedantic)\n\nadd_executable(\n  stage27_schedule_intent_tests\n  "${PROJECT_ROOT}/test/test_stage27_schedule_intent/test_main.cpp"\n  "${PROJECT_ROOT}/src/climate/runtime/Stage27ScheduleIntentAdapter.cpp"\n  "${PROJECT_ROOT}/src/climate/runtime/Stage27ScheduleProfile.cpp"\n  "${PROJECT_ROOT}/src/climate/runtime/EuropeWarsawTime.cpp"\n)\ntarget_include_directories(\n  stage27_schedule_intent_tests\n  PRIVATE\n    "${PROJECT_ROOT}/src"\n    "${PROJECT_ROOT}/lib/environment_control/src"\n)\ntarget_compile_features(stage27_schedule_intent_tests PRIVATE cxx_std_17)\ntarget_compile_options(stage27_schedule_intent_tests PRIVATE -Wall -Wextra -Wpedantic)\n\n'''
if text.count(marker) != 1:
    raise SystemExit('test/host/CMakeLists.txt target marker mismatch')
text = text.replace(marker, block)
add_test_marker = 'add_test(NAME stage27_schedule_profile_tests COMMAND stage27_schedule_profile_tests)\n'
if text.count(add_test_marker) != 1:
    raise SystemExit('test/host/CMakeLists.txt add_test marker mismatch')
text = text.replace(add_test_marker, add_test_marker + 'add_test(NAME stage27_schedule_intent_tests COMMAND stage27_schedule_intent_tests)\n')
